const assert=require('node:assert/strict'),fs=require('node:fs');
const {chromium,webkit}=require('playwright');
const engine=process.env.OVERVIEW_BROWSER||'chromium',base=process.env.OVERVIEW_URL||'http://127.0.0.1:8765/kaopu-human-overview/',out=process.env.OVERVIEW_QA_DIR||'ui-animal';fs.mkdirSync(out,{recursive:true});
const sizes=[{name:'wide',width:2048,height:1040},{name:'desktop',width:1440,height:900},{name:'phone',width:390,height:844},{name:'landscape',width:844,height:390}],routes=['','rapid-pattern-reid','4dequine-motion-appearance','animallift-canonical-fur','annotate','obj','overview'];
const report={engine,passed:false,fixtures:'Procedural two-color coordinate test images, not animal-model output or private photographs',rows:[],routes:[],errors:[],physicalPhone:false};let browser,context,page;
const save=()=>fs.writeFileSync(`${out}/ui-animal-${engine}.json`,JSON.stringify(report,null,2));
(async()=>{
 browser=await({chromium,webkit})[engine].launch({headless:true});context=await browser.newContext({viewport:sizes[0],hasTouch:true});page=await context.newPage();await context.tracing.start({screenshots:true,snapshots:true});page.on('pageerror',e=>report.errors.push(e.message));
 for(const route of routes){const url=new URL('../kaopu-animal-learning/'+(route?'#animal-learning/'+route:''),base).href;await page.goto(url,{waitUntil:'domcontentloaded'});const back=page.locator('a.overview-return');await back.waitFor();assert.equal(await back.getAttribute('target'),'_self');assert.equal(await back.evaluate(a=>a.href),base);await page.setViewportSize(sizes[2]);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:`${out}/animal-${route||'home'}-phone-${engine}.png`});await back.click();await page.waitForURL(base,{waitUntil:'domcontentloaded'});await page.goBack({waitUntil:'domcontentloaded'});await back.waitFor();assert.equal(context.pages().length,1);report.routes.push({route,returnAndReopen:true});save();}
 await page.goto(new URL('../kaopu-animal-learning/#animal-learning/annotate',base).href,{waitUntil:'domcontentloaded'});
 for(const shape of [{name:'wide',width:800,height:450},{name:'tall',width:450,height:800}]){
  const data=await page.evaluate(shape=>{const c=document.createElement('canvas');c.width=shape.width;c.height=shape.height;const g=c.getContext('2d');g.fillStyle='#657d87';g.fillRect(0,0,c.width,c.height);g.fillStyle='#d5b48b';g.fillRect(0,0,c.width/2,c.height/2);g.fillStyle='#d7ed9c';g.fillRect(c.width/2,c.height/2,c.width/2,c.height/2);return c.toDataURL('image/png').split(',')[1]},shape);
  await page.locator('#image-file').setInputFiles({name:'coordinate-fixture-'+shape.name+'.png',mimeType:'image/png',buffer:Buffer.from(data,'base64')});await page.locator('#image-stage').waitFor({state:'visible'});
  for(const size of sizes){await page.setViewportSize(size);await page.waitForTimeout(120);const label=shape.name+'-'+size.name;await page.locator('#point-label').fill(label);
   const boxes=await page.locator('#observation-image,#point-overlay,.image-viewport,.annotation-controls,.controls-scroll,#point-label').evaluateAll(es=>Object.fromEntries(es.map(e=>{const r=e.getBoundingClientRect();return[e.id||e.className,{x:r.x,y:r.y,width:r.width,height:r.height,bottom:r.bottom,right:r.right,font:getComputedStyle(e).fontSize}]})));
   const img=boxes['observation-image'],svg=boxes['point-overlay'];for(const k of ['x','y','width','height'])assert(Math.abs(img[k]-svg[k])<1,`${label}: overlay ${k}`);assert(img.height>100&&img.width>100,label+' useful image');assert(img.y>=0&&img.bottom<=size.height+1,label+' image visible');const control=boxes['point-label'];assert(control.y>=0&&control.bottom<=size.height+1,label+' control visible');assert(parseFloat(control.font)>=14);assert(control.height>=44);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),label+' overflow');
   await page.locator('#point-overlay').click({position:{x:img.width*.25,y:img.height*.25}});await page.locator('#points-list').getByText(label,{exact:false}).waitFor();const [download]=await Promise.all([page.waitForEvent('download'),page.locator('#observation-export').click()]);const file=`${out}/animal-points-${shape.name}-${size.name}-${engine}.json`;await download.saveAs(file);const record=JSON.parse(fs.readFileSync(file));const point=record.points.find(p=>p.label===label||p.name===label);assert(point,'exported point');const x=point.x??point.pixel?.[0],y=point.y??point.pixel?.[1];assert(Math.abs(x-shape.width*.25)<=3,label+' original x coordinate');assert(Math.abs(y-shape.height*.25)<=3,label+' original y coordinate');
   report.rows.push({shape,size:size.name,boxes,point});save();await page.screenshot({path:`${out}/animal-annotate-${shape.name}-${size.name}-${engine}.png`});
   if(size.name==='phone'){await page.locator('.annotation-controls>summary').click();assert.equal(await page.locator('.annotation-controls').getAttribute('open'),null);await page.waitForTimeout(80);const bigger=await page.locator('.image-viewport').boundingBox();assert(bigger.height>boxes['image-viewport'].height+60,label+' collapse grows image');await page.screenshot({path:`${out}/animal-annotate-${shape.name}-collapsed-${engine}.png`});await page.locator('.annotation-controls>summary').click();}
  }
 }
 assert.deepEqual(report.errors,[]);report.passed=true;report.version=browser.version();save();await context.tracing.stop({path:`${out}/ui-animal-trace-${engine}.zip`});await browser.close();
})().catch(async e=>{report.errors.push(e.stack||String(e));save();console.error(e);try{await page?.screenshot({path:`${out}/animal-failure-${engine}.png`});await context?.tracing.stop({path:`${out}/ui-animal-trace-${engine}.zip`});}catch{}await browser?.close();process.exit(1)});
